575→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::timer_callback)
576→{
577→	// Timer drives the serial clock when we have data to send
578→	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
579→	{
580→		// Toggle clock to shift out data
581→		m_sclk_out_cb(1);
582→		m_sclk_out_cb(0);
583→	}
584→}
