 14→
 15→DEFINE_DEVICE_TYPE(TMP94C241_SERIAL, tmp94c241_serial_device, "tmp94c241_serial", "TMP94C241 Serial Channel")
 16→
 17→tmp94c241_serial_device::tmp94c241_serial_device(const machine_config &mconfig, const char *tag, device_t *owner, uint8_t channel, uint32_t clock) :
 18→	device_t(mconfig, TMP94C241_SERIAL, tag, owner, clock),
 19→	m_channel(channel),
 20→	m_serial_control(0),
 21→	m_serial_mode(0), /* I/O interface mode and clock source at TO2 trigger */
 22→	m_baud_rate(0),
 23→	m_hz(0),
 24→	m_rx_clock_count(8),
 25→	m_rx_shift_register(0),
 26→	m_rx_buffer(0),
 27→	m_rxd(0),
 28→	m_rxd_prev(0),
 29→	m_sioclk_state(0),
 30→	m_tx_clock_count(0),
 31→	m_tx_shift_register(0),
 32→	m_txd(1),  // Idle state is HIGH for serial lines
 33→	m_sclk_out(0),
 34→	m_tx_skip_first_falling(false),
 35→	m_txd_cb(*this),
 36→	m_sclk_in_cb(*this),
 37→	m_sclk_out_cb(*this),
 38→	m_tx_start_cb(*this)
 39→{
 40→}
 41→
 42→void tmp94c241_serial_device::device_start()
 43→{
 44→	m_timer = timer_alloc(FUNC(tmp94c241_serial_device::timer_callback), this);
 45→	m_cpu = dynamic_cast<tmp94c241_device *>(owner());
 46→
 47→	save_item(NAME(m_serial_control));
 48→	save_item(NAME(m_serial_mode));
 49→	save_item(NAME(m_baud_rate));
 50→	save_item(NAME(m_hz));
 51→	save_item(NAME(m_rx_clock_count));
 52→	save_item(NAME(m_rx_shift_register));
 53→	save_item(NAME(m_rx_buffer));
 54→	save_item(NAME(m_rxd));
 55→	save_item(NAME(m_rxd_prev));
 56→	save_item(NAME(m_sioclk_state));
 57→	save_item(NAME(m_tx_clock_count));
 58→	save_item(NAME(m_tx_shift_register));
 59→	save_item(NAME(m_txd));
