  1→// license:GPL2+
  2→// copyright-holders:Felipe Sanches
  3→/***************************************************************************
  4→
  5→	KN5000 control panel HLE
  6→
  7→	Emulates the two Mitsubishi M37471M2196S MCUs on the control panel.
  8→	Since no ROM dumps are available, this uses High Level Emulation based
  9→	on reverse engineering of the main CPU firmware protocol.
 10→
 11→	Protocol documentation: https://felipesanches.github.io/kn5000-docs/control-panel-protocol/
 12→
 13→***************************************************************************/
 14→
 15→#ifndef MAME_MATSUSHITA_KN5000_CPANEL_H
 16→#define MAME_MATSUSHITA_KN5000_CPANEL_H
 17→
 18→#pragma once
 19→
 20→#include <queue>
 21→
 22→class kn5000_cpanel_device :
 23→	public device_t
 24→{
 25→public:
 26→	kn5000_cpanel_device(const machine_config &mconfig, const char *tag, device_t *owner, uint32_t clock = 0);
 27→
 28→	// Serial interface from main CPU
 29→	void rxd(int state);
 30→	void sioclk(int state);
 31→	void tx_start(int state);  // Called when CPU starts a new byte transmission
 32→
 33→	// Callbacks to main CPU
 34→	auto txd() { return m_txd_cb.bind(); }
 35→	auto sclk_out() { return m_sclk_out_cb.bind(); }
 36→	auto inta() { return m_inta_cb.bind(); }
 37→
 38→	// Configuration
 39→	void set_baudrate(uint16_t br);
 40→
 41→	// Button input port setters (called from main driver)
 42→	void set_cpl_port(int n, ioport_port *port) { m_cpl_ports[n] = port; }
 43→	void set_cpr_port(int n, ioport_port *port) { m_cpr_ports[n] = port; }
 44→
 45→protected:
 46→	// device_t overrides
 47→	virtual void device_start() override ATTR_COLD;
 48→	virtual void device_reset() override ATTR_COLD;
 49→
 50→	TIMER_CALLBACK_MEMBER(timer_callback);
 51→	TIMER_CALLBACK_MEMBER(idle_detect_callback);
 52→	TIMER_CALLBACK_MEMBER(self_clock_callback);
 53→
 54→private:
 55→	// Serial communication
 56→	void send_byte(uint8_t data);
 57→	void process_received_byte(uint8_t data);
 58→	void process_command();
 59→
 60→	// Response generation
 61→	void send_sync_packet();
 62→	void send_button_packet(int segment, bool is_left_panel);
 63→	void send_all_button_states(bool is_left_panel);
