239→{
240→	m_baud_rate = data;
241→	uint8_t divisor = data & 0x0f;
242→	uint8_t input_clocks[] = {0, 2, 8, 32};
243→	uint8_t shift_amount = (((data >> 4) & 3) + 1) * 2;
244→	logerror("baud rate: Divisor=%d  Internal Clock T%d\n", divisor, input_clocks[(data >> 4) & 3]);
245→	if (divisor)
246→	{
247→		long int fc = 16'000'000; // TODO: set this from the cpu.
248→		m_hz = (fc >> shift_amount) / divisor;
249→		m_timer->adjust(attotime::from_hz(m_hz), 0, attotime::from_hz(m_hz));
250→		logerror("timer set to %d Hz.\n", m_hz);
251→	} else {
252→		m_timer->reset(attotime::never);
253→		m_hz = 0;
254→		logerror("timer disabled.\n");
255→	}
256→	//if (m_channel == 1) machine().debug_break();
257→}
258→
259→/*
260→	0x3f means m_port_function[PORT_F]
261→
262→reset:
263→...
264→ef03d8: 08 3f 73              ld (0x3f),0x73	; disable ch.0 (bit 2) / enable ch.1 (bit 6)
265→
266→
267→Reached from which routine ?:
268→...
269→fc4068: c1 8f 8d 3e 50        or (0x8d8f),0x50	; enable channel 1 (bit 6)
270→fc406d: c1 8f 8d 21           ld A,(0x8d8f)
271→fc4071: f0 3f 41              ld (0x3f),A
272→
273→
274→SERIAL_METHOD_2:      ; FC45A8
275→...
276→fc45ab: c1 8f 8d 3e 50        or (0x8d8f),0x50	; enable channel 1 (bit 6)
277→fc45b0: c1 8f 8d 21           ld A,(0x8d8f)
278→fc45b4: f0 3f 41              ld (0x3f),A
279→
280→SERIAL_METHOD_4:       ; FC460D
281→...
282→fc4610: c1 8f 8d 3e 50        or (0x8d8f),0x50	; enable channel 1 (bit 6)
283→fc4615: c1 8f 8d 21           ld A,(0x8d8f)
284→fc4619: f0 3f 41              ld (0x3f),A
285→
286→
287→*/
288→
289→TIMER_CALLBACK_MEMBER(tmp94c241_serial_device::timer_callback)
290→{
291→	// Keep clocking while TX is in progress OR RX hasn't completed its byte.
292→	// Without the RX check, the timer stops after TX's last falling edge,
293→	// leaving RX one rising edge short of completing the byte.
294→	bool need_clock = (m_tx_clock_count > 0) || m_tx_skip_first_falling || (m_rx_clock_count != 8);
295→	if (m_hz && need_clock && (m_cpu->m_port_function[PORT_F] & (1 << (m_channel==0 ? 2: 6))))
296→	{
297→		sioclk(m_sioclk_state ^ 1);
298→	}
299→}
