{
	// The baud rate generator timer should only drive SCLK when the serial
	// module is configured to use the baud rate generator as its clock source
	// (SC_MOD bits 1:0 == 01).  When TO2 trigger is the clock source (00),
	// Timer 1's TO2_trigger() drives SCLK instead.  Without this check, both
	// the baud rate timer and TO2 would drive SCLK simultaneously, causing
	// double-clocking and data corruption.
	if ((m_serial_mode & 3) != 1)
