160→	}
161→
162→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
163→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
164→
165→	if (state)
166→	{
167→		// Rising edge: Sample RXD (receive bit from CPU)
168→		if (m_rx_clock_count > 0)
169→		{
170→			m_rx_shift_register >>= 1;
171→			m_rx_shift_register |= (m_rxd << 7);
172→			m_rx_clock_count--;
173→
174→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
175→				m_rxd, m_rx_shift_register, m_rx_clock_count);
176→
177→			if (m_rx_clock_count == 0)
178→			{
179→				// Full byte received
180→				m_rx_clock_count = 8;
181→				process_received_byte(m_rx_shift_register);
182→			}
183→		}
184→	}
185→	else
186→	{
187→		// Falling edge: Output TXD (transmit bit to CPU)
188→		// This prepares the bit for the CPU to sample on the next rising edge
189→		if (m_tx_skip_first_falling)
190→		{
191→			// Skip this falling edge - bit 0 was pre-output and we need to give
192→			// CPU a rising edge to sample it before we output bit 1
193→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
194→			m_tx_skip_first_falling = false;
195→		}
196→		else if (m_tx_clock_count > 0)
197→		{
198→			if (m_tx_clock_count == 8)
199→			{
200→				// First bit of a chained byte (loaded from queue) — output bit 0 without shifting
201→				LOGMASKED(LOG_SERIAL, "cpanel TX bit 0 (chained): %d, shift_reg=%02X\n",
202→					m_tx_shift_register & 1, m_tx_shift_register);
203→				m_txd_cb(m_tx_shift_register & 1);
204→				m_tx_clock_count--;
205→			}
206→			else
207→			{
208→				// Normal operation: shift out the next bit
209→				m_tx_shift_register >>= 1;
210→				LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
211→					m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
212→				m_txd_cb(m_tx_shift_register & 1);
213→				m_tx_clock_count--;
214→			}
215→
216→			if (m_tx_clock_count == 0)
217→			{
218→				// Byte sent, check for more
219→				if (!m_tx_queue.empty())
220→				{
221→					m_tx_shift_register = m_tx_queue.front();
222→					m_tx_queue.pop();
223→					m_tx_clock_count = 8;  // Full 8 bits — don't pre-output yet
224→
225→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte queued: %02X (no pre-output)\n",
226→						m_tx_shift_register);
227→
228→					// Don't pre-output: bit 7 of previous byte is still on the line
229→					// and needs to be sampled by CPU on the next rising edge.
230→					// Bit 0 of new byte will be output on the next falling edge.
231→				}
232→				else
233→				{
234→					// Transmission complete — leave the last bit on the line.
235→					// Do NOT call m_txd_cb(1) here: that would overwrite bit 7
236→					// of the last byte before the CPU samples it on the next
237→					// rising edge. The line will be updated when send_byte()
238→					// pre-outputs the next byte's bit 0.
239→					LOGMASKED(LOG_SERIAL, "cpanel TX done, holding last bit\n");
240→				}
241→			}
242→		}
243→	}
244→}
245→
246→void kn5000_cpanel_device::send_byte(uint8_t data)
247→{
248→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
249→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
250→
251→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
252→	{
253→		// Start sending immediately
254→		m_tx_shift_register = data;
255→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
256→
257→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
258→		m_txd_cb(m_tx_shift_register & 1);
259→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
260→			data, data & 1);
261→
262→		// Only skip the first falling edge if clock is currently HIGH.
263→		// If clock is HIGH: next edge = falling (skip it)
264→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
265→		m_tx_skip_first_falling = (m_sioclk_state == 1);
266→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
267→	}
268→	else
269→	{
270→		// Queue for later
271→		m_tx_queue.push(data);
272→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
273→	}
274→}
275→
276→void kn5000_cpanel_device::process_received_byte(uint8_t data)
277→{
278→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
279→
280→	// Ignore 0xFF when it appears as a command byte (first byte of pair).
281→	// In synchronous serial mode, the CPU must send dummy bytes to clock in
282→	// response data. These dummy 0xFF bytes are not valid commands — without
283→	// this filter they would be paired with the next real command byte,
284→	// misaligning the 2-byte command parser and potentially triggering
285→	// unintended LED commands or sync responses.
286→	if (m_cmd_index == 0 && data == 0xFF)
287→	{
288→		LOGMASKED(LOG_SERIAL, "cpanel: ignoring dummy byte 0xFF as command\n");
289→		return;
290→	}
291→
292→	m_cmd_buffer[m_cmd_index++] = data;
293→
294→	if (m_cmd_index >= 2)
295→	{
296→		// Full 2-byte command received
297→		process_command();
298→		m_cmd_index = 0;
299→	}
300→}
301→
302→void kn5000_cpanel_device::process_command()
303→{
304→	uint8_t cmd = m_cmd_buffer[0];
305→	uint8_t param = m_cmd_buffer[1];
306→
307→	// Panel selection: bits 7-5 >= 4 means right panel
308→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
309→
310→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
311→		cmd, param, is_right_panel ? "right" : "left");
312→
313→	switch (cmd)
314→	{
315→	// Initialization commands
316→	case 0x1f:  // Init sequence (left)
317→	case 0x1d:
318→	case 0x1e:
319→	case 0xdd:  // Setup mode
320→		LOGMASKED(LOG_COMMANDS, "Init command\n");
321→		send_sync_packet();
322→		m_initialized = true;
323→		break;
324→
325→	// Query commands
326→	case 0x20:  // Query left panel
327→	case 0x25:  // Query left panel (variant used in CPanel_ReadAllButtons)
328→		if (param == 0x00)
329→		{
330→			// Ping - respond with sync
331→			send_sync_packet();
332→		}
333→		else if (param <= 0x0a)
334→		{
335→			// Button segment query
336→			send_button_packet(param, true);  // left panel
337→		}
338→		else
339→		{
340→			// Status/encoder query (0x0b-0x10+) - respond with sync
341→			send_sync_packet();
342→		}
343→		break;
344→
345→	case 0xe0:  // Query right panel
346→	case 0xe2:  // Query right panel (variant used in CPanel_ReadAllButtons)
347→	case 0xe3:  // Query right panel (variant used in CPanel_InitButtonState)
348→		if (param == 0x00)
349→		{
350→			// Ping - respond with sync
351→			send_sync_packet();
352→		}
353→		else if (param <= 0x0a)
354→		{
355→			// Button segment query
356→			send_button_packet(param, false);  // right panel
357→		}
358→		else
359→		{
360→			// Status/encoder query (0x0b-0x11+) - respond with sync
361→			send_sync_packet();
362→		}
363→		break;
364→
365→	case 0x2b:  // Init button state array (left)
366→		send_all_button_states(true);
367→		break;
368→
369→	case 0xeb:  // Init button state array (right)
370→		send_all_button_states(false);
371→		break;
372→
373→	// LED control commands - right panel
374→	case 0x00:
375→	case 0x01:
376→	case 0x02:
377→	case 0x03:
378→	case 0x04:
379→	case 0x08:
380→	case 0x0a:
381→	case 0x0b:
382→	case 0x0c:
383→		process_led_command(cmd, param);
384→		send_sync_packet();
385→		break;
386→
387→	// LED control commands - left panel
388→	case 0xc0:
389→	case 0xc1:
390→	case 0xc2:
391→	case 0xc3:
392→	case 0xc4:
393→	case 0xc8:
394→		process_led_command(cmd, param);
395→		send_sync_packet();
396→		break;
397→
398→	default:
399→		// Unknown command - send sync as acknowledgment
400→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
401→		send_sync_packet();
402→		break;
403→	}
404→
405→	// Start idle detection for INTA-based response delivery.
406→	// If the CPU doesn't send dummy bytes within 250µs (i.e., the external
407→	// clock goes idle), idle_detect_callback will assert INTA and start
408→	// self-clocking to deliver the response. If the CPU does send dummy
409→	// bytes (as the AW VM does), the response gets clocked out on the CPU's
410→	// clock and idle detection is continuously retriggered, never firing.
411→	if (!m_self_clocking && (m_tx_clock_count > 0 || !m_tx_queue.empty()))
412→	{
413→		m_idle_detect_timer->adjust(attotime::from_usec(250));
414→	}
415→}
416→
417→void kn5000_cpanel_device::send_sync_packet()
418→{
419→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
420→	send_byte(0x18);
421→	send_byte(0x00);
422→}
423→
424→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
425→{
426→	if (segment < 0 || segment > 10)
427→		return 0;
428→
429→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
430→	if (port)
431→	{
432→		return port->read() & 0xff;
433→	}
434→	return 0;
435→}
436→
437→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
438→{
439→	// Button packet format:
440→	// Byte 0: [ Panel | Type | Segment ]
441→	//   - Bit 6: Panel select (0=right, 1=left)
442→	//   - Bits 5-3: Type 0 or 1 (button packet)
443→	//   - Bits 3-0 + bit 6: Segment index
444→	// Byte 1: Button state bitmap
445→
446→	uint8_t state = read_button_segment(segment, is_left_panel);
447→
448→	// For button packets, bit 6 indicates left panel
449→	uint8_t header = (segment & 0x0f);
450→	if (is_left_panel)
451→		header |= 0x40;  // Set bit 6 for left panel
452→
453→	// Type 0 for buttons (bits 5-3 = 000)
454→	send_byte(header);
455→	send_byte(state);
456→
457→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
458→		segment, is_left_panel, state);
459→
460→	// Track state for change detection
461→	int state_idx = is_left_panel ? (segment + 11) : segment;
462→	m_last_button_state[state_idx] = state;
463→}
464→
465→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
466→{
467→	// Send all 11 segments for the requested panel
468→	for (int seg = 0; seg <= 10; seg++)
469→	{
470→		send_button_packet(seg, is_left_panel);
471→	}
472→}
