474→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
475→{
476→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
477→
478→	switch (row)
479→	{
480→	// Right panel LED rows
481→	case 0x00:
482→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
483→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
484→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
485→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
486→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
487→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
488→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
489→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
490→		break;
491→
492→	case 0x01:
493→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
494→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
495→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
496→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
497→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
498→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
499→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
500→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
501→		break;
502→
503→	case 0x02:
504→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
505→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
506→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
507→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
508→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
509→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
510→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
511→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
512→		break;
513→
514→	case 0x03:
515→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
516→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
517→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
518→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
519→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
520→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
521→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
522→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
523→		break;
524→
525→	case 0x04:
526→		m_cpr_leds[33] = BIT(data, 0);  // D133 - PART SELECT: LEFT
527→		m_cpr_leds[34] = BIT(data, 1);  // D134 - PART SELECT: RIGHT 2
528→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
529→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
530→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
531→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
532→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
533→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
534→		break;
535→
536→	case 0x08:
537→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
538→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
539→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
540→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
541→		break;
542→
543→	case 0x0a:
544→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
545→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
546→		break;
547→
548→	case 0x0b:
549→		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
550→		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
551→		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
552→		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
553→		break;
554→
555→	case 0x0c:
556→		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
557→		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
558→		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
559→		m_cpr_leds[68] = BIT(data, 3);  // D168 - START/STOP 4 BEAT
560→		break;
561→
562→	// Left panel LED rows
563→	case 0xc0:
564→		m_cpl_leds[1] = BIT(data, 0);  // D101 - COMPOSER: MEMORY
565→		m_cpl_leds[2] = BIT(data, 1);  // D102 - COMPOSER: MENU
566→		m_cpl_leds[3] = BIT(data, 2);  // D103 - SOUND ARRANGER: SET
567→		m_cpl_leds[4] = BIT(data, 3);  // D104 - SOUND ARRANGER: ON/OFF
568→		m_cpl_leds[5] = BIT(data, 4);  // D105 - MUSIC STYLIST
569→		m_cpl_leds[6] = BIT(data, 5);  // D106 - FADE IN
570→		m_cpl_leds[7] = BIT(data, 6);  // D107 - FADE OUT
571→		m_cpl_leds[8] = BIT(data, 7);  // D108 - DISPLAY HOLD
572→		break;
573→
574→	case 0xc1:
575→		m_cpl_leds[9] = BIT(data, 0);   // D109 - U.S. TRAD
576→		m_cpl_leds[10] = BIT(data, 1);  // D110 - COUNTRY
577→		m_cpl_leds[11] = BIT(data, 2);  // D111 - LATIN
578→		m_cpl_leds[12] = BIT(data, 3);  // D112 - MARCH & WALTZ
579→		m_cpl_leds[13] = BIT(data, 4);  // D113 - PARTY TIME
580→		m_cpl_leds[14] = BIT(data, 5);  // D114 - SHOW TIME & TRAD DANCE
581→		m_cpl_leds[15] = BIT(data, 6);  // D115 - WORLD
582→		m_cpl_leds[16] = BIT(data, 7);  // D116 - CUSTOM
583→		break;
584→
585→	case 0xc2:
586→		m_cpl_leds[17] = BIT(data, 0);  // D117 - STANDARD ROCK
587→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
588→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
589→		m_cpl_leds[20] = BIT(data, 3);  // D120 - FUNK & FUSION
590→		m_cpl_leds[21] = BIT(data, 4);  // D121 - SOUL & MODERN DANCE
591→		m_cpl_leds[22] = BIT(data, 5);  // D122 - BIG BAND & SWING
592→		m_cpl_leds[23] = BIT(data, 6);  // D123 - JAZZ COMBO
593→		m_cpl_leds[24] = BIT(data, 7);  // D124 - MANUAL SEQUENCE PADS: MENU
594→		break;
595→
596→	case 0xc3:
597→		m_cpl_leds[25] = BIT(data, 0);  // D125 - VARIATION & MSA 1
598→		m_cpl_leds[26] = BIT(data, 1);  // D126 - VARIATION & MSA 2
599→		m_cpl_leds[27] = BIT(data, 2);  // D127 - VARIATION & MSA 3
600→		m_cpl_leds[28] = BIT(data, 3);  // D128 - VARIATION & MSA 4
601→		m_cpl_leds[29] = BIT(data, 4);  // D129 - MUSIC STYLE ARRANGER
602→		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
603→		break;
604→
605→	case 0xc4:
606→		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
607→		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
608→		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
609→		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
610→		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
611→		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
612→		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
613→		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
614→		break;
615→
616→	case 0xc8:
617→		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
618→		break;
619→	}
620→}
