633→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::idle_detect_callback)
634→{
635→	// The external serial clock (from CPU) has been idle for 250µs.
636→	// If we have pending response data, the CPU is not going to send
637→	// dummy bytes to clock it out — switch to self-clocking mode and
638→	// assert INTA so the CPU's firmware can enable receive mode.
639→
640→	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
641→	{
642→		LOGMASKED(LOG_SERIAL, "cpanel: external clock idle, asserting INTA and starting self-clock\n");
643→
644→		// Assert INTA to notify the CPU that we have data
645→		if (!m_inta_asserted)
646→		{
647→			m_inta_asserted = true;
648→			m_inta_cb(1);
649→		}
650→
651→		// Start self-clocking after a brief delay to let the CPU process
652→		// the INTA interrupt and enable receive mode.
653→		// 50µs ≈ 800 CPU cycles at 16 MHz — plenty for the ISR.
654→		m_self_clocking = true;
655→		m_self_clock_timer->adjust(attotime::from_usec(50), 0, attotime::from_hz(250000));
656→	}
657→}
658→
659→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::self_clock_callback)
660→{
661→	// Drive one clock edge per callback (toggle), matching the CPU serial
662→	// timer's behavior. At 250 kHz, this gives 125 kHz SCLK = one bit
663→	// every 8µs, one byte every 64µs.
664→	m_sclk_out_cb(m_sioclk_state ^ 1);
665→	// The edge propagates: cpanel sclk_out → CPU serial sioclk → CPU serial
666→	// sclk_out → cpanel sioclk. Both sides process the edge.
667→
668→	// Check if we're done transmitting
669→	if (m_tx_clock_count == 0 && m_tx_queue.empty())
670→	{
671→		LOGMASKED(LOG_SERIAL, "cpanel: self-clock TX complete, deasserting INTA\n");
672→		m_self_clocking = false;
673→		m_self_clock_timer->reset(attotime::never);
674→
675→		if (m_inta_asserted)
676→		{
677→			m_inta_asserted = false;
678→			m_inta_cb(0);
679→		}
680→	}
681→}
