 49→	m_cmd_index(0),
 50→	m_initialized(false),
 51→	m_self_clocking(false),
 52→	m_inta_asserted(false),
 53→	m_txd_cb(*this),
 54→	m_sclk_out_cb(*this),
 55→	m_inta_cb(*this),
 56→	m_cpl_leds(*this, "cpl_led_%u", 0U),
 57→	m_cpr_leds(*this, "cpr_led_%u", 0U)
 58→{
 59→	std::fill(std::begin(m_cmd_buffer), std::end(m_cmd_buffer), 0);
 60→	std::fill(std::begin(m_last_button_state), std::end(m_last_button_state), 0);
 61→	std::fill(std::begin(m_cpl_ports), std::end(m_cpl_ports), nullptr);
 62→	std::fill(std::begin(m_cpr_ports), std::end(m_cpr_ports), nullptr);
 63→}
