 65→void kn5000_cpanel_device::device_start()
 66→{
 67→	m_timer = timer_alloc(FUNC(kn5000_cpanel_device::timer_callback), this);
 68→	m_idle_detect_timer = timer_alloc(FUNC(kn5000_cpanel_device::idle_detect_callback), this);
 69→	m_self_clock_timer = timer_alloc(FUNC(kn5000_cpanel_device::self_clock_callback), this);
 70→
 71→	// Resolve LED outputs
 72→	m_cpl_leds.resolve();
 73→	m_cpr_leds.resolve();
 74→
 75→	// Save state
 76→	save_item(NAME(m_baud_rate));
 77→	save_item(NAME(m_rx_clock_count));
 78→	save_item(NAME(m_rx_shift_register));
 79→	save_item(NAME(m_rxd));
 80→	save_item(NAME(m_sioclk_state));
 81→	save_item(NAME(m_tx_clock_count));
 82→	save_item(NAME(m_tx_shift_register));
 83→	save_item(NAME(m_tx_skip_first_falling));
 84→	save_item(NAME(m_cmd_buffer));
 85→	save_item(NAME(m_cmd_index));
 86→	save_item(NAME(m_initialized));
 87→	save_item(NAME(m_self_clocking));
 88→	save_item(NAME(m_inta_asserted));
 89→	save_item(NAME(m_last_button_state));
 90→
 91→	// Initial state - line idle high
 92→	m_txd_cb(1);
 93→}
