 95→void kn5000_cpanel_device::device_reset()
 96→{
 97→	m_baud_rate = 0;
 98→	m_rx_clock_count = 8;
 99→	m_tx_clock_count = 0;
100→	m_tx_skip_first_falling = false;
101→	m_cmd_index = 0;
102→	m_initialized = false;
103→	m_self_clocking = false;
104→	m_inta_asserted = false;
105→
106→	// Clear TX queue
107→	while (!m_tx_queue.empty())
108→		m_tx_queue.pop();
109→
110→	m_idle_detect_timer->reset(attotime::never);
111→	m_self_clock_timer->reset(attotime::never);
112→
113→	std::fill(std::begin(m_last_button_state), std::end(m_last_button_state), 0);
114→}
