135→
136→void kn5000_cpanel_device::tx_start(int state)
137→{
138→	// Called when CPU starts transmitting a new byte - reset RX to sync byte boundaries
139→	if (state)
140→	{
141→		LOGMASKED(LOG_SERIAL, "cpanel tx_start: resetting RX counter for sync\n");
142→		m_rx_clock_count = 8;
143→		m_rx_shift_register = 0;
144→	}
145→}
146→
147→void kn5000_cpanel_device::sioclk(int state)
148→{
149→	if (m_sioclk_state == state)
150→		return;
151→
152→	m_sioclk_state = state;
153→
154→	// If we're not self-clocking and we have a pending response, retrigger
155→	// the idle detect timer.  When it expires (250µs of no SCLK edges), we
156→	// know the CPU has stopped driving SCLK and we should self-clock to
157→	// deliver the response via INTA.
158→	//
159→	// Only retrigger when response data is pending (m_tx_clock_count > 0 or
160→	// queue non-empty).  During the firmware's TX init phases (phantom bytes
161→	// with PFFC disabled), the CPU serial doesn't forward SCLK to us, so we
162→	// don't see edges.  Without this guard, idle_detect could fire prematurely
163→	// between the real command bytes (the inter-byte gap exceeds 250µs because
164→	// phantom bytes are clocked slowly by TO2_trigger at ~12.5kHz).
165→	if (!m_self_clocking && (m_tx_clock_count > 0 || !m_tx_queue.empty()))
166→	{
167→		m_idle_detect_timer->adjust(attotime::from_usec(250));
168→	}
169→
170→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
171→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
172→
173→	if (state)
174→	{
175→		// Rising edge: Sample RXD (receive bit from CPU)
176→		// Skip RX during self-clocking: we are transmitting a response and
177→		// the CPU serial may still be shifting out a phantom byte from a
178→		// previous TX phase.  Those bits arrive on our RXD line and would
179→		// be misinterpreted as new commands, queuing additional responses
180→		// that prevent self-clocking from ever completing (INTA stays
181→		// asserted, breaking the next command exchange).
182→		if (!m_self_clocking && m_rx_clock_count > 0)
183→		{
184→			m_rx_shift_register >>= 1;
185→			m_rx_shift_register |= (m_rxd << 7);
186→			m_rx_clock_count--;
187→
188→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
189→				m_rxd, m_rx_shift_register, m_rx_clock_count);
190→
191→			if (m_rx_clock_count == 0)
192→			{
193→				// Full byte received
194→				m_rx_clock_count = 8;
195→				process_received_byte(m_rx_shift_register);
196→			}
197→		}
198→	}
199→	else
200→	{
201→		// Falling edge: Output TXD (transmit bit to CPU)
202→		// This prepares the bit for the CPU to sample on the next rising edge
203→		if (m_tx_skip_first_falling)
204→		{
205→			// Skip this falling edge - bit 0 was pre-output and we need to give
206→			// CPU a rising edge to sample it before we output bit 1
207→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
208→			m_tx_skip_first_falling = false;
209→		}
210→		else if (m_tx_clock_count > 0)
211→		{
212→			if (m_tx_clock_count == 8)
213→			{
214→				// First bit of a chained byte (loaded from queue) — output bit 0 without shifting
215→				LOGMASKED(LOG_SERIAL, "cpanel TX bit 0 (chained): %d, shift_reg=%02X\n",
216→					m_tx_shift_register & 1, m_tx_shift_register);
217→				m_txd_cb(m_tx_shift_register & 1);
218→				m_tx_clock_count--;
219→			}
220→			else
221→			{
222→				// Normal operation: shift out the next bit
223→				m_tx_shift_register >>= 1;
224→				LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
225→					m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
226→				m_txd_cb(m_tx_shift_register & 1);
227→				m_tx_clock_count--;
228→			}
229→
230→			if (m_tx_clock_count == 0)
231→			{
232→				// Byte sent, check for more
233→				if (!m_tx_queue.empty())
234→				{
235→					m_tx_shift_register = m_tx_queue.front();
236→					m_tx_queue.pop();
237→					m_tx_clock_count = 8;  // Full 8 bits — don't pre-output yet
238→
239→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte queued: %02X (no pre-output)\n",
240→						m_tx_shift_register);
241→
242→					// Don't pre-output: bit 7 of previous byte is still on the line
243→					// and needs to be sampled by CPU on the next rising edge.
244→					// Bit 0 of new byte will be output on the next falling edge.
245→				}
246→				else
247→				{
248→					// Transmission complete — leave the last bit on the line.
249→					// Do NOT call m_txd_cb(1) here: that would overwrite bit 7
250→					// of the last byte before the CPU samples it on the next
251→					// rising edge. The line will be updated when send_byte()
252→					// pre-outputs the next byte's bit 0.
253→					LOGMASKED(LOG_SERIAL, "cpanel TX done, holding last bit\n");
254→
255→					// Cancel idle detect — the response has been fully delivered
256→					// (clocked out by the CPU's dummy bytes or external clock).
257→					// Without this, idle_detect would fire 250us later and
258→					// assert INTA unnecessarily, potentially crashing firmware
259→					// that doesn't have an INTA handler (e.g., the AW VM).
260→					m_idle_detect_timer->reset(attotime::never);
261→				}
262→			}
263→		}
264→	}
265→}
266→
267→void kn5000_cpanel_device::send_byte(uint8_t data)
268→{
269→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
270→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
271→
272→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
273→	{
274→		// Start sending immediately
275→		m_tx_shift_register = data;
276→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
277→
278→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
279→		m_txd_cb(m_tx_shift_register & 1);
280→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
281→			data, data & 1);
282→
283→		// Only skip the first falling edge if clock is currently HIGH.
284→		// If clock is HIGH: next edge = falling (skip it)
285→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
286→		m_tx_skip_first_falling = (m_sioclk_state == 1);
287→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
288→	}
289→	else
290→	{
291→		// Queue for later
292→		m_tx_queue.push(data);
293→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
294→	}
295→}
296→
297→void kn5000_cpanel_device::process_received_byte(uint8_t data)
298→{
299→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
300→
301→	// Ignore 0xFF when it appears as a command byte (first byte of pair).
302→	// In synchronous serial mode, the CPU must send dummy bytes to clock in
303→	// response data. These dummy 0xFF bytes are not valid commands — without
304→	// this filter they would be paired with the next real command byte,
305→	// misaligning the 2-byte command parser and potentially triggering
306→	// unintended LED commands or sync responses.
307→	if (m_cmd_index == 0 && data == 0xFF)
308→	{
309→		LOGMASKED(LOG_SERIAL, "cpanel: ignoring dummy byte 0xFF as command\n");
310→		return;
311→	}
312→
313→	m_cmd_buffer[m_cmd_index++] = data;
314→
315→	if (m_cmd_index >= 2)
316→	{
317→		// Full 2-byte command received
318→		process_command();
319→		m_cmd_index = 0;
320→	}
321→}
322→
323→void kn5000_cpanel_device::process_command()
324→{
325→	uint8_t cmd = m_cmd_buffer[0];
326→	uint8_t param = m_cmd_buffer[1];
327→
328→	// Panel selection: bits 7-5 >= 4 means right panel
329→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
330→
331→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
332→		cmd, param, is_right_panel ? "right" : "left");
333→
334→	switch (cmd)
335→	{
336→	// Initialization commands
337→	case 0x1f:  // Init sequence (left)
338→	case 0x1d:
339→	case 0x1e:
340→	case 0xdd:  // Setup mode
341→		LOGMASKED(LOG_COMMANDS, "Init command\n");
342→		send_sync_packet();
343→		m_initialized = true;
344→		break;
345→
346→	// Query commands
347→	case 0x20:  // Query left panel
348→	case 0x25:  // Query left panel (variant used in CPanel_ReadAllButtons)
349→		if (param == 0x00)
350→		{
351→			// Ping - respond with sync
352→			send_sync_packet();
353→		}
354→		else if (param <= 0x0a)
355→		{
356→			// Button segment query
357→			send_button_packet(param, true);  // left panel
358→		}
359→		else
360→		{
361→			// Status/encoder query (0x0b-0x10+) - respond with sync
362→			send_sync_packet();
363→		}
364→		break;
365→
366→	case 0xe0:  // Query right panel
367→	case 0xe2:  // Query right panel (variant used in CPanel_ReadAllButtons)
368→	case 0xe3:  // Query right panel (variant used in CPanel_InitButtonState)
369→		if (param == 0x00)
370→		{
371→			// Ping - respond with sync
372→			send_sync_packet();
373→		}
374→		else if (param <= 0x0a)
375→		{
376→			// Button segment query
377→			send_button_packet(param, false);  // right panel
378→		}
379→		else
380→		{
381→			// Status/encoder query (0x0b-0x11+) - respond with sync
382→			send_sync_packet();
383→		}
384→		break;
385→
386→	case 0x2b:  // Init button state array (left)
387→		send_all_button_states(true);
388→		break;
389→
390→	case 0xeb:  // Init button state array (right)
391→		send_all_button_states(false);
392→		break;
393→
394→	// LED control commands - right panel
395→	case 0x00:
396→	case 0x01:
397→	case 0x02:
398→	case 0x03:
399→	case 0x04:
400→	case 0x08:
401→	case 0x0a:
402→	case 0x0b:
403→	case 0x0c:
404→		process_led_command(cmd, param);
405→		send_sync_packet();
406→		break;
407→
408→	// LED control commands - left panel
409→	case 0xc0:
410→	case 0xc1:
411→	case 0xc2:
412→	case 0xc3:
413→	case 0xc4:
414→	case 0xc8:
415→		process_led_command(cmd, param);
416→		send_sync_packet();
417→		break;
418→
419→	default:
420→		// Unknown command - send sync as acknowledgment
421→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
422→		send_sync_packet();
423→		break;
424→	}
425→
426→	// Start idle detection for INTA-based response delivery.
427→	// If the CPU doesn't send dummy bytes within 250µs (i.e., the external
428→	// clock goes idle), idle_detect_callback will assert INTA and start
429→	// self-clocking to deliver the response. If the CPU does send dummy
430→	// bytes (as the AW VM does), the response gets clocked out on the CPU's
431→	// clock and idle detection is continuously retriggered, never firing.
432→	if (!m_self_clocking && (m_tx_clock_count > 0 || !m_tx_queue.empty()))
433→	{
434→		m_idle_detect_timer->adjust(attotime::from_usec(250));
435→	}
436→}
437→
438→void kn5000_cpanel_device::send_sync_packet()
439→{
440→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
441→	send_byte(0x18);
442→	send_byte(0x00);
443→}
444→
445→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
446→{
447→	if (segment < 0 || segment > 10)
448→		return 0;
449→
450→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
451→	if (port)
452→	{
453→		return port->read() & 0xff;
454→	}
455→	return 0;
456→}
457→
458→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
459→{
460→	// Button packet format:
461→	// Byte 0: [ Panel | Type | Segment ]
462→	//   - Bit 6: Panel select (0=right, 1=left)
463→	//   - Bits 5-3: Type 0 or 1 (button packet)
464→	//   - Bits 3-0 + bit 6: Segment index
465→	// Byte 1: Button state bitmap
466→
467→	uint8_t state = read_button_segment(segment, is_left_panel);
468→
469→	// For button packets, bit 6 indicates left panel
470→	uint8_t header = (segment & 0x0f);
471→	if (is_left_panel)
472→		header |= 0x40;  // Set bit 6 for left panel
473→
474→	// Type 0 for buttons (bits 5-3 = 000)
475→	send_byte(header);
476→	send_byte(state);
477→
478→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
479→		segment, is_left_panel, state);
480→
481→	// Track state for change detection
482→	int state_idx = is_left_panel ? (segment + 11) : segment;
483→	m_last_button_state[state_idx] = state;
484→}
485→
486→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
487→{
488→	// Send all 11 segments for the requested panel
489→	for (int seg = 0; seg <= 10; seg++)
490→	{
491→		send_button_packet(seg, is_left_panel);
492→	}
493→}
494→
495→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
496→{
497→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
498→
499→	switch (row)
500→	{
501→	// Right panel LED rows
502→	case 0x00:
503→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
504→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
505→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
506→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
507→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
508→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
509→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
510→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
511→		break;
512→
513→	case 0x01:
514→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
515→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
516→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
517→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
518→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
519→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
520→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
521→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
522→		break;
523→
524→	case 0x02:
525→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
526→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
527→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
528→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
529→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
530→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
531→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
532→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
533→		break;
534→
535→	case 0x03:
536→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
537→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
538→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
539→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
540→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
541→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
542→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
543→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
544→		break;
545→
546→	case 0x04:
547→		m_cpr_leds[33] = BIT(data, 0);  // D133 - PART SELECT: LEFT
548→		m_cpr_leds[34] = BIT(data, 1);  // D134 - PART SELECT: RIGHT 2
549→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
550→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
551→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
552→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
553→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
554→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
555→		break;
556→
557→	case 0x08:
558→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
559→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
560→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
561→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
562→		break;
563→
564→	case 0x0a:
565→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
566→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
567→		break;
568→
569→	case 0x0b:
570→		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
571→		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
572→		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
573→		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
574→		break;
575→
576→	case 0x0c:
577→		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
578→		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
579→		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
580→		m_cpr_leds[68] = BIT(data, 3);  // D168 - START/STOP 4 BEAT
581→		break;
582→
583→	// Left panel LED rows
584→	case 0xc0:
585→		m_cpl_leds[1] = BIT(data, 0);  // D101 - COMPOSER: MEMORY
586→		m_cpl_leds[2] = BIT(data, 1);  // D102 - COMPOSER: MENU
587→		m_cpl_leds[3] = BIT(data, 2);  // D103 - SOUND ARRANGER: SET
588→		m_cpl_leds[4] = BIT(data, 3);  // D104 - SOUND ARRANGER: ON/OFF
589→		m_cpl_leds[5] = BIT(data, 4);  // D105 - MUSIC STYLIST
590→		m_cpl_leds[6] = BIT(data, 5);  // D106 - FADE IN
591→		m_cpl_leds[7] = BIT(data, 6);  // D107 - FADE OUT
592→		m_cpl_leds[8] = BIT(data, 7);  // D108 - DISPLAY HOLD
593→		break;
594→
595→	case 0xc1:
596→		m_cpl_leds[9] = BIT(data, 0);   // D109 - U.S. TRAD
597→		m_cpl_leds[10] = BIT(data, 1);  // D110 - COUNTRY
598→		m_cpl_leds[11] = BIT(data, 2);  // D111 - LATIN
599→		m_cpl_leds[12] = BIT(data, 3);  // D112 - MARCH & WALTZ
600→		m_cpl_leds[13] = BIT(data, 4);  // D113 - PARTY TIME
601→		m_cpl_leds[14] = BIT(data, 5);  // D114 - SHOW TIME & TRAD DANCE
602→		m_cpl_leds[15] = BIT(data, 6);  // D115 - WORLD
603→		m_cpl_leds[16] = BIT(data, 7);  // D116 - CUSTOM
604→		break;
605→
606→	case 0xc2:
607→		m_cpl_leds[17] = BIT(data, 0);  // D117 - STANDARD ROCK
608→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
609→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
610→		m_cpl_leds[20] = BIT(data, 3);  // D120 - FUNK & FUSION
611→		m_cpl_leds[21] = BIT(data, 4);  // D121 - SOUL & MODERN DANCE
612→		m_cpl_leds[22] = BIT(data, 5);  // D122 - BIG BAND & SWING
613→		m_cpl_leds[23] = BIT(data, 6);  // D123 - JAZZ COMBO
614→		m_cpl_leds[24] = BIT(data, 7);  // D124 - MANUAL SEQUENCE PADS: MENU
615→		break;
616→
617→	case 0xc3:
618→		m_cpl_leds[25] = BIT(data, 0);  // D125 - VARIATION & MSA 1
619→		m_cpl_leds[26] = BIT(data, 1);  // D126 - VARIATION & MSA 2
620→		m_cpl_leds[27] = BIT(data, 2);  // D127 - VARIATION & MSA 3
621→		m_cpl_leds[28] = BIT(data, 3);  // D128 - VARIATION & MSA 4
622→		m_cpl_leds[29] = BIT(data, 4);  // D129 - MUSIC STYLE ARRANGER
623→		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
624→		break;
625→
