627→		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
628→		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
629→		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
630→		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
631→		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
632→		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
633→		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
634→		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
635→		break;
636→
637→	case 0xc8:
638→		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
639→		break;
