641→}
642→
643→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::timer_callback)
644→{
645→	// Timer drives the serial clock when we have data to send
646→	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
647→	{
648→		// Toggle clock to shift out data
649→		m_sclk_out_cb(1);
650→		m_sclk_out_cb(0);
651→	}
652→}
653→
654→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::idle_detect_callback)
655→{
656→	// The external serial clock (from CPU) has been idle for 250µs.
657→	// If we have pending response data, the CPU is not going to send
658→	// dummy bytes to clock it out — switch to self-clocking mode and
659→	// assert INTA so the CPU's firmware can enable receive mode.
660→
661→	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
662→	{
663→		LOGMASKED(LOG_SERIAL, "cpanel: external clock idle, asserting INTA and starting self-clock\n");
664→
665→		// Assert INTA to notify the CPU that we have data
666→		if (!m_inta_asserted)
667→		{
668→			m_inta_asserted = true;
669→			m_inta_cb(1);
670→		}
671→
672→		// Start self-clocking after a brief delay to let the CPU process
673→		// the INTA interrupt and enable receive mode.
674→		// 50µs ≈ 800 CPU cycles at 16 MHz — plenty for the ISR.
675→		m_self_clocking = true;
676→		m_self_clock_timer->adjust(attotime::from_usec(50), 0, attotime::from_hz(250000));
677→	}
678→}
679→
680→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::self_clock_callback)
681→{
682→	// Drive one clock edge per callback (toggle), matching the CPU serial
683→	// timer's behavior. At 250 kHz, this gives 125 kHz SCLK = one bit
684→	// every 8µs, one byte every 64µs.
685→	m_sclk_out_cb(m_sioclk_state ^ 1);
686→	// The edge propagates: cpanel sclk_out → CPU serial sioclk → CPU serial
687→	// sclk_out → cpanel sioclk. Both sides process the edge.
688→
689→	// Check if we're done transmitting
690→	if (m_tx_clock_count == 0 && m_tx_queue.empty())
691→	{
692→		LOGMASKED(LOG_SERIAL, "cpanel: self-clock TX complete, deasserting INTA\n");
693→		m_self_clocking = false;
694→		m_self_clock_timer->reset(attotime::never);
695→
696→		if (m_inta_asserted)
697→		{
698→			m_inta_asserted = false;
699→			m_inta_cb(0);
700→		}
701→	}
702→}
703→

