 88→
 89→	// Command buffer (2-byte commands)
 90→	uint8_t m_cmd_buffer[2];
 91→	uint8_t m_cmd_index;
 92→
 93→	// Protocol state
 94→	bool m_initialized;
 95→	bool m_self_clocking;
 96→	bool m_inta_asserted;
 97→	uint8_t m_last_button_state[22];  // 11 segments * 2 panels
 98→
 99→	// Callbacks
100→	devcb_write_line m_txd_cb;
101→	devcb_write_line m_sclk_out_cb;
102→	devcb_write_line m_inta_cb;
103→
104→	// Input port pointers (set by main driver)
